from typing import List, Dict, Any

def main_solution(operations: List[Dict[str, Any]]) -> Dict[str, str]:
    """
    Simulates a key-value map with add, delete, and modify operations.

    Operations:
    - 'add': key -> value
    - 'delete': remove key
    - 'modify': key -> new_value

    Returns the final state of the map as a dictionary.
    """
    map_state: Dict[str, str] = {}

    for op in operations:
        action = op['action']
        key = op['key']
        value = op.get('value', '')

        if action == 'add':
            map_state[key] = value
        elif action == 'delete':
            if key in map_state:
                del map_state[key]
        elif action == 'modify':
            if key in map_state:
                map_state[key] = value

    return map_state
